items.starterCode:
function calculateTotal(usageEvents, tier) {
  // TODO: api_call rate is 0.001 for 'standard', 0.0005 for 'enterprise'
  // everything else stays 0.01 regardless of tier
}

items.solution:
function calculateTotal(usageEvents, tier) {
  return usageEvents.reduce((sum, event) => {
    let rate;
    if (event.type === 'api_call') {
      rate = tier === 'enterprise' ? 0.0005 : 0.001;
    } else {
      rate = 0.01;
    }
    return sum + event.quantity * rate;
  }, 0);
}

